const academyEscape=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const academyLink=s=>/^https:\/\//.test(s)?academyEscape(s):'#';
function academySourceList(sources=[]){return `<div class="academy-sources">${sources.map((s,i)=>`<div><a href="${academyLink(s.url)}" target="_blank" rel="noopener">${i+1}. ${academyEscape(s.title)} ↗</a><small>${academyEscape(s.organization||'')}${s.date?' · '+academyEscape(s.date):''}</small><p>${academyEscape(s.note||'')}</p></div>`).join('')}</div>`}
function lessonFurtherReading(l){return `${l.pitfalls?.length?`<section class="lesson-check"><h3>停下来检查一下</h3><ul>${l.pitfalls.map(p=>`<li>${academyEscape(p)}</li>`).join('')}</ul></section>`:''}<section class="lesson-references"><h3>本课出处与延伸阅读</h3><p class="subtitle">正文为中文教学讲义，算例采用自设条件；以下原始资料支持原理或制度说明。旧课程材料用于学习原理，现行政策另查有日期的文件。</p>${academySourceList(l.sources)}<a class="source-link" data-lesson-resources href="#resources">教材与公开课程导读 →</a></section>`}
function lessonResearchTask(l){if(!l.assignment)return '';const a=l.assignment;return `<section class="research-task"><span class="tag">综合研究任务 · 自查</span><h3>用自己的资料，完成一个分析</h3><p>${academyEscape(a.prompt)}</p><ol>${a.checks.map(x=>`<li>${academyEscape(x)}</li>`).join('')}</ol><details><summary>怎样判断报告是否完整？</summary><p>${academyEscape(a.sample)}</p></details><p class="subtitle">这是开放研究任务，请自行核对证据和计算。下方概念题只检查本课知识点。</p></section>`}
function academySaveText(name,text){const blob=new Blob(['\uFEFF'+text],{type:'text/markdown;charset=utf-8'}),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1500)}
function lessonNotes(l,g){return `# ${l.title}\n\n${l.desc}\n\n目标：${g.goal}\n\n${l.sections.map(([t,p])=>`## ${t}\n\n${p}`).join('\n\n')}\n\n## 完整示例\n\n${g.example.join('\n\n')}\n\n## 独立练习\n\n${g.task?g.task[0]+'\n\n参考答案：'+g.task[1]+' '+g.task[2]+'\n\n'+g.task[3]:l.quiz.q+'\n\n'+l.quiz.options.map((x,i)=>`${i+1}. ${x}`).join('\n')+'\n\n参考答案：'+l.quiz.options[l.quiz.answer]+'。'+l.quiz.explain}\n\n${l.assignment?'## 研究任务\n\n'+l.assignment.prompt+'\n\n'+l.assignment.checks.join('\n')+'\n\n'+l.assignment.sample+'\n\n':''}## 常见误区\n\n${(l.pitfalls||[]).join('\n\n')}\n\n## 来源与延伸阅读\n\n${(l.sources||[]).map(s=>`- [${s.title}](${s.url}) — ${s.organization||''}${s.date?'；'+s.date:''}。${s.note||''}`).join('\n')}\n\n资料整理日期：2026-10-07。此文件为本站教学讲义，不包含第三方教材全文。\n`}
function downloadLessonNotes(l,g){academySaveText(`电力市场讲义-${l.id}-${l.title}.md`,lessonNotes(l,g))}
function academyBindLessons(scope=app){scope.querySelectorAll('[data-lesson]').forEach(b=>b.onclick=()=>openLesson(Number(b.dataset.lesson)))}
function academyCourseCard(id){const l=lessons.find(x=>x.id===id),g=lessonGuides[id];return `<article class="lesson ${id===learningNext()?'recommended':''}"><span class="tag">${learningOrder.indexOf(id)+1} / ${lessons.length} · ${l.minutes} 分钟${animationKinds[id]?' · 含动画':''}${id===learningNext()?' · 推荐下一课':''}</span><h3>${academyEscape(l.title)}</h3><p>${academyEscape(g.goal)}</p><small class="prerequisite">${g.pre.length?'建议先学：'+g.pre.map(id=>academyEscape(lessons.find(x=>x.id===id).title)).join('、'):'无需专业基础 · 会加减乘除即可'}</small><div class="lesson-actions"><button class="secondary" data-lesson="${id}">${completed.includes(id)?'复习课程':'开始学习'} →</button><span class="done">${completed.includes(id)?'✓ 已学完':'待学习'}</span></div></article>`}
function academyCourses(){app.innerHTML=heading('从零基础，到独立分析一个市场','六个模块串起工程、经济、合同、政策与项目；每课都有讲义、算例、练习和出处。','课程路线')+`<div class="academy-overview"><div><strong>${lessons.length}</strong><span>递进课程</span></div><div><strong>${lessons.filter(l=>lessonGuides[l.id].task).length}</strong><span>数值练习</span></div><div><strong>${new Set(worldMarkets.map(m=>m.country)).size}</strong><span>国家参考</span></div><div><strong>${learningResources.length}</strong><span>教材与课程资源</span></div></div><div class="learning-method"><span>01 先预测结果</span><span>02 跟着示例算</span><span>03 换条件独立练习</span><span>04 对照来源与真实规则</span></div><div class="academy-filters"><input id="courseSearch" aria-label="搜索课程" placeholder="搜索主题、术语或课程…"><select id="courseStage" aria-label="选择学习模块"><option value="">全部模块</option>${learningGroups.map((s,i)=>`<option value="${i}">${i+1}. ${academyEscape(s.title)}</option>`).join('')}</select></div><p id="courseCount" class="subtitle" role="status"></p><div id="courseResults"></div><section class="panel"><h2>术语随手查</h2><p class="subtitle">一句话起步，再读本课解释和适用规则。</p><div class="glossary-grid">${Object.entries(glossary).map(([t,d])=>`<details><summary>${academyEscape(t)}</summary><p>${academyEscape(d)}</p></details>`).join('')}</div></section>`;
 const update=()=>{const q=document.getElementById('courseSearch').value.trim().toLowerCase(),stage=document.getElementById('courseStage').value;let n=0;document.getElementById('courseResults').innerHTML=learningGroups.map((s,i)=>{if(stage!==''&&Number(stage)!==i)return '';const ids=s.ids.filter(id=>{const l=lessons.find(x=>x.id===id),g=lessonGuides[id];return !q||[l.title,l.desc,g.goal,...g.terms,...l.sections.flat()].join(' ').toLowerCase().includes(q)});n+=ids.length;return ids.length?`<section class="course-stage"><div class="course-stage-heading"><span class="stage-num">0${i+1}</span><div><h2>${academyEscape(s.title)}</h2><p class="subtitle">${academyEscape(s.desc)}</p></div></div><div class="lesson-grid">${ids.map(academyCourseCard).join('')}</div></section>`:''}).join('')||'<div class="panel empty">没有匹配课程。试试“成本”“容量”“基差”或清除筛选。</div>';document.getElementById('courseCount').textContent=`显示 ${n} / ${lessons.length} 节课；可自由选课，建议沿先修关系学习。`;academyBindLessons()};document.getElementById('courseSearch').oninput=update;document.getElementById('courseStage').onchange=update;update();}
function resourcesView(){app.innerHTML=heading('教材与公开课程，带着问题读','先用本站中文讲义理解，再沿原始资料深入。','教材与资源')+`<div class="notice">本站保存课程讲义、原创算例、阅读指南及已收录的省级资料。这里区分公开课程、官方教程和教材书目；第三方全文是否开放及转载许可逐项注明。访问日期为2026-10-07，历史课程不作为现行政策依据。</div><div class="resource-paths">${resourceReadingPaths.map(p=>`<article class="panel"><h2>${academyEscape(p.title)}</h2><p>${academyEscape(p.goal)}</p><ol>${p.ids.map(id=>{const r=learningResources.find(x=>x.id===id);return `<li><a href="#resource-${id}">${academyEscape(r.title)}</a></li>`}).join('')}</ol></article>`).join('')}</div><div class="resource-export"><span>导出本站完整中文讲义、练习参考答案与来源，便于离线复习。</span><button class="secondary" id="exportCourses">导出课程讲义 ↓</button></div><div class="academy-filters"><input id="resourceSearch" aria-label="搜索教材与资源" placeholder="搜索书名、机构或主题…"><select id="resourceKind" aria-label="资源类型"><option value="">全部类型</option>${[...new Set(learningResources.map(r=>r.kind))].map(x=>`<option>${academyEscape(x)}</option>`).join('')}</select><select id="resourceLanguage" aria-label="资源语言"><option value="">全部语言</option>${[...new Set(learningResources.map(r=>r.language))].map(x=>`<option>${academyEscape(x)}</option>`).join('')}</select></div><p class="subtitle" id="resourceCount" role="status"></p><div class="resource-grid" id="resourceResults"></div>`;
 const update=()=>{const q=document.getElementById('resourceSearch').value.trim().toLowerCase(),kind=document.getElementById('resourceKind').value,lang=document.getElementById('resourceLanguage').value,found=learningResources.filter(r=>(!kind||r.kind===kind)&&(!lang||r.language===lang)&&(!q||[r.title,r.organization,r.author,r.description,...r.topics].join(' ').toLowerCase().includes(q)));document.getElementById('resourceCount').textContent=`${found.length} 项资源`;document.getElementById('resourceResults').innerHTML=found.map(r=>`<article class="panel resource-card" id="resource-${r.id}"><div><span class="tag">${academyEscape(r.kind)}</span> <span class="tag">${academyEscape(r.language)}</span></div><h2>${academyEscape(r.title)}</h2><p class="resource-byline">${academyEscape(r.author||r.organization)}${r.author?' · '+academyEscape(r.organization):''}</p><p>${academyEscape(r.description)}</p><details><summary>怎么读这份资料？</summary><ol>${r.path.map(x=>`<li>${academyEscape(x)}</li>`).join('')}</ol><p>${academyEscape(r.license)}${r.licenseUrl?` <a class="source-link" href="${academyLink(r.licenseUrl)}" target="_blank" rel="noopener">许可说明 ↗</a>`:''}</p></details><dl class="resource-meta"><dt>开放程度</dt><dd>${academyEscape(r.access)}</dd><dt>资料日期</dt><dd>${academyEscape(r.date)}</dd></dl><div class="resource-lessons">${r.lessonIds.slice(0,4).map(id=>`<button class="text-link" data-lesson="${id}">${academyEscape(lessons.find(l=>l.id===id).title)} →</button>`).join('')}</div><a class="secondary" href="${academyLink(r.url)}" target="_blank" rel="noopener">${r.kind==='教材书目'?'查看书目与原始资源':'打开原始资源'} ↗</a></article>`).join('')||'<div class="panel empty">没有匹配资源，请调整关键词或筛选。</div>';academyBindLessons()};['resourceSearch','resourceKind','resourceLanguage'].forEach(id=>document.getElementById(id).addEventListener('input',update));document.getElementById('exportCourses').onclick=()=>academySaveText('电力市场学堂-完整课程讲义.md',learningOrder.map(id=>{const l=lessons.find(x=>x.id===id);return lessonNotes(l,lessonGuides[id])}).join('\n\n---\n\n'));update();
 // Reading path links scroll within this page without changing the app route.
 app.querySelectorAll('.resource-paths a').forEach(a=>a.onclick=e=>{e.preventDefault();const id=a.getAttribute('href').slice(1);document.getElementById('resourceSearch').value='';document.getElementById('resourceKind').value='';document.getElementById('resourceLanguage').value='';update();document.getElementById(id)?.scrollIntoView({block:'start'})});}
const worldFields=[['governance','谁管理、谁运营'],['sequence','交易与交付时序'],['pricing','价格形成与口径'],['balance','平衡与辅助服务'],['adequacy','充裕性与容量安排'],['transition','新能源、储能与灵活负荷']];
function worldCitations(m,key){const ids=m.fieldSources?.[key]||m.sources.map((_,i)=>i);return `<span class="world-citations">${ids.map(i=>`<a href="${academyLink(m.sources[i].url)}" target="_blank" rel="noopener" title="${academyEscape(m.sources[i].title)}">[${i+1}]</a>`).join(' ')}</span>`}
function internationalView(id){const m=worldMarkets.find(m=>m.id===id);if(m){worldDetail(m);return}app.innerHTML=heading('国际电力市场：同一组问题，不同制度','从国家与区域边界出发，比较交易、价格、平衡、可靠性和灵活资源。','国际比较')+`<div class="notice">首批覆盖 ${new Set(worldMarkets.map(m=>m.country)).size} 个国家、${worldMarkets.length} 个国家或区域案例。以下是有来源的教学摘要，并非所有国家的完整现行法规合集。来源访问日期：2026-10-07；改革生效时间和地域边界在详情中分别注明。</div><div class="world-start"><div><h2>第一次比较？先学方法</h2><p>不要先比较两个国家的均价。先统一区域、主体、产品、时段和费用口径。</p></div><button class="secondary" data-lesson="27">开始国际比较课 →</button></div><section class="panel compare-panel"><h2>选择两个市场，对照阅读</h2><div class="compare-selects"><label>市场 A<select id="compareA">${worldMarkets.map(x=>`<option value="${x.id}">${academyEscape(x.name)}</option>`).join('')}</select></label><label>市场 B<select id="compareB">${worldMarkets.map(x=>`<option value="${x.id}">${academyEscape(x.name)}</option>`).join('')}</select></label></div><div id="worldComparison"></div></section><div class="academy-filters"><input id="worldSearch" aria-label="搜索国际市场" placeholder="搜索国家、机构或机制…"><select id="worldRegion" aria-label="选择世界地区"><option value="">全部地区</option>${[...new Set(worldMarkets.map(x=>x.region))].map(x=>`<option>${academyEscape(x)}</option>`).join('')}</select><select id="worldModel" aria-label="选择市场方式"><option value="">全部市场方式</option>${[...new Set(worldMarkets.map(x=>x.model))].map(x=>`<option>${academyEscape(x)}</option>`).join('')}</select></div><p class="subtitle" id="worldCount" role="status"></p><div class="world-grid" id="worldResults"></div>`;document.getElementById('compareB').value='us-pjm';const compare=()=>{const a=worldMarkets.find(x=>x.id===document.getElementById('compareA').value),b=worldMarkets.find(x=>x.id===document.getElementById('compareB').value);document.getElementById('worldComparison').innerHTML=`<div class="comparison-title"><a class="source-link" href="#international/${a.id}">${academyEscape(a.name)}详情 →</a><a class="source-link" href="#international/${b.id}">${academyEscape(b.name)}详情 →</a></div>${[['scope','适用范围'],...worldFields].map(([k,t])=>`<section class="comparison-row"><h3>${t}</h3><div><article><span class="comparison-market">${academyEscape(a.name)}</span><p>${academyEscape(a[k])} ${k==='scope'?'':worldCitations(a,k)}</p></article><article><span class="comparison-market">${academyEscape(b.name)}</span><p>${academyEscape(b[k])} ${k==='scope'?'':worldCitations(b,k)}</p></article></div></section>`).join('')}`};['compareA','compareB'].forEach(id=>document.getElementById(id).onchange=compare);compare();const update=()=>{const q=document.getElementById('worldSearch').value.trim().toLowerCase(),region=document.getElementById('worldRegion').value,model=document.getElementById('worldModel').value,found=worldMarkets.filter(m=>(!region||m.region===region)&&(!model||m.model===model)&&(!q||[m.name,m.summary,m.governance,...m.tags].join(' ').toLowerCase().includes(q)));document.getElementById('worldCount').textContent=`${found.length} 个案例`;document.getElementById('worldResults').innerHTML=found.map(m=>`<article class="panel world-card"><span class="tag">${academyEscape(m.region)}</span><h2>${academyEscape(m.name)}</h2><p>${academyEscape(m.summary)}</p><p class="world-scope">范围：${academyEscape(m.scope)}</p><div class="world-tags">${m.tags.map(x=>`<span class="tag">${academyEscape(x)}</span>`).join('')}</div><a class="secondary" href="#international/${m.id}">阅读机制与算例 →</a></article>`).join('')||'<div class="panel empty">未找到对应案例。首批覆盖范围有限，请调整筛选。</div>'};['worldSearch','worldRegion','worldModel'].forEach(id=>document.getElementById(id).addEventListener('input',update));update();academyBindLessons();}
function worldDetail(m){app.innerHTML=`<a class="source-link world-back" href="#international">← 国际比较</a>`+heading(m.name,m.summary,'国际市场案例')+`<div class="world-detail-meta"><span class="tag">${academyEscape(m.model)}</span><p><b>适用范围：</b>${academyEscape(m.scope)}</p><p>来源访问：${m.checked}。访问日不代表所有制度的生效日。</p></div><div class="world-detail-grid"><div>${worldFields.map(([k,t])=>`<section class="panel world-section"><h2>${t}</h2><p>${academyEscape(m[k])} ${worldCitations(m,k)}</p></section>`).join('')}<section class="panel world-section"><span class="tag">原创教学算例 · 自设条件</span><h2>${academyEscape(m.case.title)}</h2><p>${academyEscape(m.case.body)}</p><div class="formula">${academyEscape(m.case.formula)}</div><p><b>${academyEscape(m.case.result)}</b></p><p class="subtitle">模型边界：${academyEscape(m.case.boundary)}</p></section><section class="panel world-section"><h2>阅读时记住</h2><p>${academyEscape(m.caution)}</p><button class="secondary" data-lesson="28">学习价格口径与基差 →</button> <button class="secondary" id="exportMarket">导出本案笔记 ↓</button></section></div><aside class="panel world-references"><h2>官方出处</h2><p class="subtitle">段落旁的编号对应以下来源；旧原理资料与改革文件需结合阅读。</p>${academySourceList(m.sources)}<a class="source-link" href="#resources">教材与公开课程 →</a></aside></div>`;academyBindLessons();document.getElementById('exportMarket').onclick=()=>academySaveText(`国际市场-${m.country}-${m.id}.md`,`# ${m.name}\n\n范围：${m.scope}\n\n${m.summary}\n\n${worldFields.map(([k,t])=>`## ${t}\n\n${m[k]}`).join('\n\n')}\n\n## 原创教学算例\n\n${Object.values(m.case).join('\n\n')}\n\n${m.caution}\n\n## 官方来源\n\n${m.sources.map((s,i)=>`${i+1}. [${s.title}](${s.url}) — ${s.organization}；${s.date||'页面未标注日期'}。${s.note}`).join('\n')}\n\n来源访问日期：${m.checked}。\n`);}
